const test=require('node:test'),assert=require('node:assert/strict');
const modules=()=>Promise.all([import('../vendor/three.module.js'),import('../atmosphere-description.js'),import('../atmosphere-render.js'),import('../atmosphere-host.js')]);
test('weather suppression preserves night sky; indoors suppresses all sky',async()=>{const [,{atmosphere}]=await modules();for(const weather of ['clouds','rain','snow','mist'])for(const options of [{intensity:0},{environment:'vacuum'},{environment:'interior'}]){const a=atmosphere({time:'night',weather,...options});assert.equal(a.weather,'clear');assert.equal(a.clouds.length,0);assert.equal(a.particles.length,0);assert.equal(a.fog,null);assert.equal(a.stars.length>0,options.environment!=='interior');}assert.throws(()=>atmosphere({intensity:NaN}));});
test('atmosphere motion validates time, respects reduced motion and disposes exactly once',async()=>{const [T,{atmosphere},{renderAtmosphere}]=await modules();const effect=renderAtmosphere(T,atmosphere({weather:'rain',time:'day',reducedMotion:true}));const points=effect.group.children.find(o=>o.isPoints),before=Array.from(points.geometry.attributes.position.array);effect.update(50);assert.deepEqual(Array.from(points.geometry.attributes.position.array),before);assert.throws(()=>effect.update(NaN));assert.throws(()=>effect.update(-1));const resources=new Set();effect.group.traverse(o=>{if(o.geometry)resources.add(o.geometry);for(const m of [].concat(o.material||[]))resources.add(m);});let count=0;for(const r of resources)r.addEventListener('dispose',()=>count++);effect.dispose();effect.dispose();effect.update(NaN);assert.equal(count,resources.size);});
test('host restores exact fog/background/light state and never owns model resources',async()=>{const [T,,,{createAtmosphereHost}]=await modules();const scene=new T.Scene(),background=new T.Color('#123456'),fog=new T.Fog('#abcdef',2,50),light=new T.DirectionalLight('#fffddd',2),model=new T.Mesh(new T.BoxGeometry(),new T.MeshStandardMaterial());scene.background=background;scene.fog=fog;scene.add(light,model);let disposed=0;model.geometry.addEventListener('dispose',()=>disposed++);model.material.addEventListener('dispose',()=>disposed++);const host=createAtmosphereHost(T,scene,{center:new T.Vector3(),span:10,lights:[light]});host.set({time:'night',weather:'mist'});assert.notEqual(scene.fog,fog);assert.throws(()=>host.set({intensity:NaN}));assert.equal(host.read().time,'night');host.set({enabled:false});assert.equal(scene.fog,fog);assert.equal(scene.background,background);assert.equal(light.intensity,2);assert.equal(light.color.getHexString(),'fffddd');host.set({environment:'interior',time:'night',weather:'snow'});assert.equal(scene.background,background);assert.equal(host.read().moon,false);host.dispose();host.dispose();assert.equal(disposed,0);assert.equal(scene.children.length,2);});
